public static void main(String[] args) {
    test("parses day/month/year", () -> eq(parseDate("05/02/2024"), LocalDate.of(2024, 2, 5)));
    test("accepts a real leap day", () -> eq(parseDate("29/02/2024"), LocalDate.of(2024, 2, 29)));
    test("refuses an impossible date instead of fixing it", () -> {
        raises(DateTimeParseException.class, () -> parseDate("31/02/2024"));
        raises(DateTimeParseException.class, () -> parseDate("29/02/2023"));
    });
    test("refuses other layouts", () -> {
        raises(DateTimeParseException.class, () -> parseDate("2024-02-05"));
        raises(DateTimeParseException.class, () -> parseDate("5/2/2024"));
    });
    test("labels a date in English", () -> eq(label(LocalDate.of(2024, 2, 5)), "Mon 05 Feb 2024"));
    test("the label ignores the machine's locale", () -> {
        var saved = Locale.getDefault();
        Locale.setDefault(Locale.FRANCE);
        try {
            eq(label(LocalDate.of(2024, 12, 25)), "Wed 25 Dec 2024");
        } finally {
            Locale.setDefault(saved);
        }
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    var noon = at("2024-03-10T12:00:00Z", "UTC");
    test("charges per day late", () -> eq(new LateFees(noon, 25, 500).feeFor(LocalDate.of(2024, 3, 7)), 75));
    test("never charges more than the cap", () -> eq(new LateFees(noon, 25, 500).feeFor(LocalDate.of(2024, 1, 1)), 500));
    test("due today costs nothing", () -> eq(new LateFees(noon, 25, 500).feeFor(LocalDate.of(2024, 3, 10)), 0));
    test("due in the future costs nothing", () -> eq(new LateFees(noon, 25, 500).feeFor(LocalDate.of(2024, 4, 1)), 0));
    test("isOverdue starts the day after the due date", () -> {
        var fees = new LateFees(noon, 25, 500);
        eq(fees.isOverdue(LocalDate.of(2024, 3, 10)), false);
        eq(fees.isOverdue(LocalDate.of(2024, 3, 9)), true);
    });
    test("today is the date in the clock's zone", () -> {
        var tokyo = at("2024-03-10T23:30:00Z", "Asia/Tokyo");
        var london = at("2024-03-10T23:30:00Z", "Europe/London");
        eq(new LateFees(tokyo, 25, 500).feeFor(LocalDate.of(2024, 3, 10)), 25);
        eq(new LateFees(london, 25, 500).feeFor(LocalDate.of(2024, 3, 10)), 0);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("bills on the same day each month", () -> eq(
        billingDates(LocalDate.of(2024, 1, 15), 3),
        List.of(LocalDate.of(2024, 1, 15), LocalDate.of(2024, 2, 15), LocalDate.of(2024, 3, 15))));
    test("a month-end schedule never drifts", () -> eq(
        billingDates(LocalDate.of(2024, 1, 31), 4),
        List.of(LocalDate.of(2024, 1, 31), LocalDate.of(2024, 2, 29), LocalDate.of(2024, 3, 31), LocalDate.of(2024, 4, 30))));
    test("February outside a leap year", () -> eq(
        billingDates(LocalDate.of(2023, 1, 30), 3),
        List.of(LocalDate.of(2023, 1, 30), LocalDate.of(2023, 2, 28), LocalDate.of(2023, 3, 30))));
    test("crosses a year end", () -> eq(
        billingDates(LocalDate.of(2024, 11, 30), 3),
        List.of(LocalDate.of(2024, 11, 30), LocalDate.of(2024, 12, 30), LocalDate.of(2025, 1, 30))));
    test("zero dates is an empty schedule", () -> eq(billingDates(LocalDate.of(2024, 1, 1), 0), List.of()));
    test("describes a gap in months and days", () ->
        eq(describeGap(LocalDate.of(2024, 1, 31), LocalDate.of(2024, 3, 1)), "1 month 1 day"));
    test("leaves out zero parts and pluralises", () -> {
        eq(describeGap(LocalDate.of(2023, 1, 15), LocalDate.of(2025, 1, 18)), "2 years 3 days");
        eq(describeGap(LocalDate.of(2024, 5, 1), LocalDate.of(2024, 7, 1)), "2 months");
    });
    test("no gap is zero days", () -> eq(describeGap(LocalDate.of(2024, 5, 1), LocalDate.of(2024, 5, 1)), "0 days"));
    System.exit(report());
}
